#!/usr/bin/env python3
"""
Rewrite power ops:  x**y  ->  Interval.pow(x, y)

Usage:
  python rewrite_pow.py < input.txt > output.txt

Or edit `expr = ...` at the bottom for a quick test.
"""

import ast
import sys


class PowToIntervalPow(ast.NodeTransformer):
    def visit_BinOp(self, node: ast.BinOp) -> ast.AST:
        node = self.generic_visit(node)  # transform children first
        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Pow):
            return ast.copy_location(
                ast.Call(
                    func=ast.Attribute(
                        value=ast.Name(id="Interval", ctx=ast.Load()),
                        attr="pow",
                        ctx=ast.Load(),
                    ),
                    args=[node.left, node.right],
                    keywords=[],
                ),
                node,
            )
        return node


def rewrite(expr: str) -> str:
    tree = ast.parse(expr, mode="eval")
    tree = PowToIntervalPow().visit(tree)
    ast.fix_missing_locations(tree)
    return ast.unparse(tree)  # Python 3.9+


